package tasks

import "context"

// AwaitCommandsAfterTurn is what a non-interactive session does once a turn has
// ended, for a harness that waits for the background commands owner still has
// running too: it returns the next finished task of owner, to start a further
// turn, and nil when there is nothing left to wait for.
func (r *Registry) AwaitCommandsAfterTurn(ctx context.Context, owner string) *Task {
	for {
		if t := r.takeFirstFinished(owner); t != nil {
			return t
		}
		if !r.runningOf(owner, true) {
			return nil
		}
		select {
		case <-r.changed:
		case <-ctx.Done():
			return nil
		}
	}
}
